    let name = "Fido"
    func describe() -> String { "I am \(name)" }
}

// This works with anything describable, now or later
func show(_ thing: Describable) {
    print(thing.describe())
}

protocol Greeter {
    func hi()           // in the list: can be replaced
}

extension Greeter {
    func hi()  { print("from the protocol") }   // default for 'hi'
    func bye() { print("from the protocol") }   // NOT in the list
}

