// weak must be var and optional: ARC has to be able to write nil into it
class Screen {
    weak var delegate: ScreenDelegate?
}

// ': AnyObject' is what makes the weak below legal
protocol ListDelegate: AnyObject {
    func didSelect(_ index: Int)
}

final class ListView {
    weak var delegate: ListDelegate?     // the child does not keep the parent alive
}

final class Screen: ListDelegate {
    let list = ListView()                // the parent holds the child: strong
    init() { list.delegate = self }      // and back: weak. No cycle.
    func didSelect(_ index: Int) {}
}

final class ViewModel {
    var onChange: (() -> Void)?

    func bindBadly() {
        onChange = { self.reload() }          // leak: self holds the closure,
    }                                          // the closure holds self

    func bindWell() {
        onChange = { [weak self] in
            guard let self else { return }     // already gone? nothing to do
            self.reload()
        }
    }

    func fine() {
        DispatchQueue.main.async { self.reload() }   // no cycle: released after it runs
    }

    func reload() {}
}

// The cheapest check there is
deinit { print("\(type(of: self)) freed") }

// A repeating timer leaks even with [weak self]
final class Clock {
    private var timer: Timer?

    func start() {
        timer = Timer.scheduledTimer(withTimeInterval: 1, repeats: true) { [weak self] _ in
            self?.tick()
        }
    }

    deinit { timer?.invalidate() }   // this is the part people forget

    func tick() {}
}

